import { useState, useEffect, useRef } from 'react';
import { searchCharacters , getCharacterById, getRelatedSubjects} from './BangumiRequest';
import styles from './styles/InputStyles.module.css';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper
} from '@mui/material';

function SearchDropdown() {
    const [inputTerm, setInputTerm] = useState('');
    const [results, setResults] = useState({value : [], completed : false});
    const [isLoading, setIsLoading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const [history, setHistory] = useState({value : [], updated : false});
    const dropdownRef = useRef(null);

    const findChineseName = (infobox) => {
        const res = infobox.find(item => item.key === "简体中文名");
        return res?.value;
    }

    // 点击外部关闭下拉框
    useEffect(() => {
        const handleClickOutside = (event) => {
        if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
            setIsOpen(false);
        }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // 搜索函数
    const handleSearch = () => {
        if (!inputTerm.trim()) {
        setResults({value : [], completed : true});
        return;
        }

        setIsLoading(true);
        setIsOpen(true);
        setResults({value : [], completd : false});

        searchCharacters(inputTerm)
        .then(response => {
            setResults({value : response.data, completed : true}); // 标记搜索已完成
            //console.log('搜索结果：',response,results.value,results.completed,typeof results.value,results.value.length);
        })
        .catch(error => {
            console.error('搜索失败:', error);
            setResults({value : [], completd : true}); // 即使出错也标记完成
        })
        .finally(() => {
            setIsLoading(false);
        });
    };

    const handleClick = (item) => {
        getRelatedSubjects(item.id).then((response) => {
            let temp = {person : item, index : previousHistory.value.length + 1, related : response.filter(item => (item.type === 2))};
            setHistory(previousHistory => {return {value : [...previousHistory.value, temp], updated : true}});
        });
    }

    return (
        <div className="App">
        <h1> 猜猜呗</h1>
        <div className={styles.searchContainer} ref={dropdownRef}>
        <div className={styles.searchBox}>
            <input
            type="text"
            value={inputTerm}
            onChange={(e) => setInputTerm(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
            placeholder="输入角色名..."
            className={styles.searchInput}
            />
            <button
            onClick={handleSearch}
            disabled={isLoading}
            className={styles.searchButton}
            >
            {isLoading ? '搜索中...' : '搜索'}
            </button>
        </div>

        {/* 下拉框 - 根据状态精确控制显示内容 */}
        {isOpen && (
            <div className={styles.largeSearchArea}>
            {isLoading ? (
                <div className={styles.dropdownItem}>加载中...</div>
            ) : results.completed ? ( // 只有搜索完成后再判断结果
                (typeof results.value == typeof [] && results.value.length > 0) ? (
                results.value.map(item => (
                    <div
                    key={item.id}
                    className={styles.dropdownItem}
                    onClick={() => {
                        handleClick(item);
                        setInputTerm('');
                        setIsOpen(false);
                    }}
                    >
                    {item.name}  {findChineseName(item.infobox)}
                    </div>
                ))
                ) : (
                <div className={styles.dropdownItem}>未找到结果</div>
                )
            ) : null}
            </div>
        )}
        </div>
        <div>
            <TableContainer component={Paper}>
                <Table size="small">
                <TableHead>
                    <TableRow>
                    <TableCell>序号</TableCell>
                    <TableCell>人物原名</TableCell>
                    <TableCell>人物中文名</TableCell>
                    <TableCell>性别</TableCell>
                    <TableCell>作品数</TableCell>
                    <TableCell>热度</TableCell>
                    </TableRow>
                </TableHead>
                <TableBody>
                    {history.value.length > 0 ? (
                        history.value.map(item => (
                            <TableRow key={item.index}>
                            <TableCell>{item.index}</TableCell>
                            <TableCell>{item.person.name}</TableCell>
                            <TableCell>{findChineseName(item.person.infobox)}</TableCell>
                            <TableCell>{item.person.gender}</TableCell>
                            <TableCell>{item.related.length}</TableCell>
                            <TableCell>{item.person.stat.collects}</TableCell>
                            </TableRow>
                        ))
                    ) : (
                        <TableRow>
                            <TableCell colSpan={4} align="center">
                            暂无搜索历史
                            </TableCell>
                        </TableRow>
                    )}
                </TableBody>
                </Table>
            </TableContainer>
        </div>
        </div>
    );
}

export default SearchDropdown;
